From 0321d4302963939b8f6dcd96f90c621a7c7659d1 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:07:40 +0100
Subject: [PATCH] kded: close activity-bound vaults two minutes after leaving
 the activity

Switching to an activity a vault doesn't belong to closed it right away,
so a quick look at another activity meant unlocking it again. Now it
only closes after 120 s away (plasmavaultrc General/ActivityCloseDelay).

BUG: 385984
---
 kded/service.cpp | 38 +++++++++++++++++++++++++++++++++++++-
 1 file changed, 37 insertions(+), 1 deletion(-)

diff --git a/kded/service.cpp b/kded/service.cpp
index ea44606..f32ee07 100644
--- a/kded/service.cpp
+++ b/kded/service.cpp
@@ -11,6 +11,7 @@
 #include <QMessageBox>
 #include <QProcess>
 #include <QSocketNotifier>
+#include <QTimer>

 #include <KApplicationTrader>
 #include <KConfigGroup>
@@ -65,6 +66,7 @@ class PlasmaVaultService::Private
 public:
     QHash<Device, Vault *> knownVaults;
     QSet<Device> openVaults;
+    QHash<Device, QTimer *> activityCloseTimers;
     KActivities::Consumer kamd;

     QFile mountsFile;
@@ -521,11 +523,45 @@ void PlasmaVaultService::onActivitiesChanged(const QStringList &knownActivities)

 void PlasmaVaultService::onCurrentActivityChanged(const QString &currentActivity)
 {
+    const auto config = KSharedConfig::openConfig(PLASMAVAULT_CONFIG_FILE);
+    const int closeDelay = KConfigGroup(config, "General").readEntry("ActivityCloseDelay", 120);
+
     for (auto *vault : d->knownVaults.values()) {
+        const auto device = vault->device();
         const auto vaultActivities = vault->activities();
-        if (!vaultActivities.isEmpty() && !vaultActivities.contains(currentActivity)) {
+
+        if (vaultActivities.isEmpty() || vaultActivities.contains(currentActivity)) {
+            delete d->activityCloseTimers.take(device);
+            continue;
+        }
+
+        if (closeDelay <= 0) {
             vault->close();
+            continue;
+        }
+
+        if (!vault->isOpened() || d->activityCloseTimers.contains(device)) {
+            continue;
         }
+
+        auto timer = new QTimer(this);
+        timer->setSingleShot(true);
+        timer->setInterval(closeDelay * 1000);
+        connect(timer, &QTimer::timeout, this, [this, device] {
+            d->activityCloseTimers.take(device)->deleteLater();
+
+            auto vault = d->vaultFor(device.data());
+            if (!vault || !vault->isOpened()) {
+                return;
+            }
+
+            const auto vaultActivities = vault->activities();
+            if (!vaultActivities.isEmpty() && !vaultActivities.contains(d->kamd.currentActivity())) {
+                vault->close();
+            }
+        });
+        d->activityCloseTimers.insert(device, timer);
+        timer->start();
     }
 }

